    'vatCodes.kind.investment.when': 'Il giustificativo indica l’IVA svizzera a questa aliquota, e il costo è un costo d’esercizio o un acquisto di beni (conti 1xxx, 5xxx–6xxx). L’imposta contenuta nell’importo è imposta precedente nella cifra 405.',
