    'vatCodes.kind.depositRelief.when': 'Un bene acquistato senza deduzione dell’imposta precedente (prima dell’assoggettamento o per un’attività esclusa) serve ora a prestazioni imponibili: l’imposta precedente sul suo valore attuale si deduce a posteriori (art. 32 LIVA). Cifra 410.',
    'vatCodes.kind.depositRelief.notWhen': 'Acquisti ordinari con giustificativo IVA: I81 o M81.',
    'vatCodes.kind.inputCorrection.name': 'Correzione dell’imposta precedente (quota privata, consumo proprio)',
    'vatCodes.kind.inputCorrection.when': 'Un costo la cui imposta precedente è stata dedotta interamente serve in parte a scopi privati (abbonamento mobile, laptop, automobile). La quota privata passa al conto corrente del titolare e il codice restituisce l’imposta precedente relativa (art. 31 LIVA). La cifra 415 riduce l’imposta precedente.',
    'vatCodes.kind.inputCorrection.notWhen': 'Un acquisto interamente privato: non registrarlo come costo, o stornarlo con il codice negativo (-I81). Riduzione per sussidi: K81-C.',
    'vatCodes.kind.inputReduction.name': 'Riduzione della deduzione dell’imposta precedente',
    'vatCodes.kind.inputReduction.when': 'L’impresa riceve sussidi o contributi pubblici simili (art. 18 cpv. 2 lett. a–c LIVA); l’imposta precedente è ridotta in proporzione (art. 33). La cifra 420 riduce l’imposta precedente.',
    'vatCodes.kind.inputReduction.notWhen': 'Quota privata: K81-B. Doni e dividendi non riducono l’imposta precedente.',
