    'desktop.q.vatRegistered.ask': 'Iscritta nel registro IVA?',
    'desktop.q.vatRegistered.why': 'Obbligatoria da CHF 100’000 di cifra d’affari all’anno; sotto, un’azienda può iscriversi volontariamente ed è allora iscritta. Solo un’azienda iscritta registra con codici IVA e rendiconta.',
