    'desktop.q.vatRegistered.no': 'no',
    'desktop.q.vatRegistered.no.caveat': 'Acquisti e vendite sono registrati al lordo, senza codici IVA, e non c’è rendiconto IVA. La pagina IVA controlla la cifra d’affari dell’anno civile rispetto alla soglia di assoggettamento.',
    'desktop.q.vatMethod.ask': 'Metodo IVA',
    'desktop.q.vatMethod.why': 'Effettivo: paghi l’IVA che hai fatturato, meno l’IVA sui tuoi acquisti (imposta precedente). Aliquota saldo: un’aliquota concessa dall’AFC sulla cifra d’affari, senza questa deduzione.',
    'desktop.q.vatMethod.where': 'Non sei sicuro? Rendiconta con l’aliquota saldo un’azienda che l’ha chiesta e a cui l’AFC ha concesso un’aliquota; si rendiconta con il modulo 0553. La tua fiduciaria lo sa. Scelta sbagliata? La cambi sotto Azienda › IVA finché quest’anno non ha registrazioni.',
    'desktop.q.vatMethod.effective': 'metodo effettivo',
