    'desktop.q.vatMethod.net-rate.caveat': 'Le vendite sono registrate al lordo con l’aliquota saldo approvata (una o due, come autorizzato dall’AFC), gli acquisti al lordo senza imposta precedente; il rendiconto è il modulo 0553, semestrale. L’app chiede poi l’aliquota.',
    'desktop.q.basis.ask': 'Modalità di rendiconto',
