    'desktop.q.basis.where': 'Non sei sicuro? La legge prevede le controprestazioni convenute; ricevute vale se l’azienda l’ha chiesto, all’iscrizione o più tardi, e l’AFC l’ha concesso. La tua fiduciaria lo sa. Scelta sbagliata? La cambi sotto Azienda › IVA finché quest’anno non ha registrazioni.',
    'desktop.q.noVat': 'Non rendicontiamo l’IVA',
